import * as stylex from '@stylexjs/stylex';

// Design tokens — the single file users edit to retheme their app.
// Familiar semantic names (background, foreground, muted, accent, ...).
//
// Each color is a `light-dark(light, dark)` pair: the browser picks a side
// from the CSS `color-scheme` in scope, which `colorScheme` in `themes.ts`
// sets on <html>. Edit both sides when you change a color.
//
// Colors use oklch (perceptually uniform; easy to shift lightness/chroma).
// Avoid legacy comma syntax like `rgba(0, 0, 0, 0.5)` — the shadcn CLI's
// transformer mangles comma number lists; `oklch(0% 0 0deg / 50%)` is safe.
//
// There is no font token: components inherit the page's font. Set
// `font-family` on <html> (popups portal to <body> and inherit it too).

export const colors = stylex.defineVars({
  background: 'light-dark(oklch(1 0 0), oklch(0.145 0 0))',
  foreground: 'light-dark(oklch(0.145 0 0), oklch(0.985 0 0))',
  card: 'light-dark(oklch(1 0 0), oklch(0.205 0 0))',
  cardForeground: 'light-dark(oklch(0.145 0 0), oklch(0.985 0 0))',
  popover: 'light-dark(oklch(1 0 0), oklch(0.205 0 0))',
  popoverForeground: 'light-dark(oklch(0.145 0 0), oklch(0.985 0 0))',
  primary: 'light-dark(oklch(0.205 0 0), oklch(0.922 0 0))',
  primaryForeground: 'light-dark(oklch(0.985 0 0), oklch(0.205 0 0))',
  secondary: 'light-dark(oklch(0.97 0 0), oklch(0.269 0 0))',
  secondaryForeground: 'light-dark(oklch(0.205 0 0), oklch(0.985 0 0))',
  muted: 'light-dark(oklch(0.97 0 0), oklch(0.269 0 0))',
  mutedForeground: 'light-dark(oklch(0.556 0 0), oklch(0.708 0 0))',
  accent: 'light-dark(oklch(0.97 0 0), oklch(0.269 0 0))',
  accentForeground: 'light-dark(oklch(0.205 0 0), oklch(0.985 0 0))',
  destructive: 'light-dark(oklch(0.577 0.245 27.325), oklch(0.704 0.191 22.216))',
  destructiveForeground: 'light-dark(oklch(0.985 0 0), oklch(0.205 0 0))',
  border: 'light-dark(oklch(0.922 0 0), oklch(0.269 0 0))',
  input: 'light-dark(oklch(0.922 0 0), oklch(0.325 0 0))',
  ring: 'light-dark(oklch(0.708 0 0), oklch(0.556 0 0))',
  overlay: 'light-dark(oklch(0% 0 0deg / 50%), oklch(0% 0 0deg / 70%))',
  // Categorical series palette for charts (chart.tsx maps these onto the
  // chart library's palette variables). Six slots, in assignment order.
  chart1: 'light-dark(oklch(0.646 0.222 41.116), oklch(0.488 0.243 264.376))',
  chart2: 'light-dark(oklch(0.6 0.118 184.704), oklch(0.696 0.17 162.48))',
  chart3: 'light-dark(oklch(0.398 0.07 227.392), oklch(0.769 0.188 70.08))',
  chart4: 'light-dark(oklch(0.828 0.189 84.429), oklch(0.627 0.265 303.9))',
  chart5: 'light-dark(oklch(0.769 0.188 70.08), oklch(0.645 0.246 16.439))',
  chart6: 'light-dark(oklch(0.55 0.2 300), oklch(0.7 0.15 200))',
});

export const radius = stylex.defineVars({
  // Small chrome that would read as a pill at the next step up: the resize
  // handle's grip, and anything else narrower than 2x this radius.
  xs: '0.25rem',
  sm: '0.375rem',
  md: '0.5rem',
  lg: '0.625rem',
  xl: '0.75rem',
  full: '9999px',
});

// Shadows stay hex-alpha: the CLI parses shadow shorthands separately and
// mangles oklch() inside them.
export const shadow = stylex.defineVars({
  sm: '0 1px 2px #0000000d',
  md: '0 4px 8px -2px #0000001a',
  lg: '0 10px 20px -5px #00000026',
});

import * as stylex from '@stylexjs/stylex';

// Non-themed scales (compile-time constants — see STYLEX.md). Themable tokens
// (colors, radius, fonts, shadows) live in tokens.stylex.ts as defineVars.

// Spacing scale in 0.25rem (4px) steps; sNN = NN * 0.25rem.
export const space = stylex.defineConsts({
  px: '1px',
  s05: '0.125rem',
  s1: '0.25rem',
  s15: '0.375rem',
  s2: '0.5rem',
  s25: '0.625rem',
  s3: '0.75rem',
  s4: '1rem',
  s5: '1.25rem',
  s6: '1.5rem',
  s7: '1.75rem',
  s8: '2rem',
  s9: '2.25rem',
  s10: '2.5rem',
  s12: '3rem',
  s16: '4rem',
});

export const fontSize = stylex.defineConsts({
  xs: '0.75rem',
  sm: '0.875rem',
  base: '1rem',
  lg: '1.125rem',
  xl: '1.5rem',
});

export const lineHeight = stylex.defineConsts({
  none: '1',
  tight: '1.3',
  snug: '1.4',
  normal: '1.5',
  // Single-line control text (paired with fontSize.sm, like Tailwind's
  // text-sm 14/20). A 20px line box centers on whole pixels inside our
  // control heights — ratio-based heights land on half pixels and make
  // Base UI's align-item-with-trigger text drift by 1px.
  control: '1.25rem',
});

export const fontWeight = stylex.defineConsts({
  medium: '500',
  semibold: '600',
  bold: '700',
});

export const z = stylex.defineConsts({
  popup: '50',
  toast: '100',
});

export const duration = stylex.defineConsts({
  fast: '150ms',
  // Modal-tier surfaces (dialog, sheet): big enough to read as deliberate,
  // still under the 300ms ceiling for UI motion.
  normal: '200ms',
  // Larger surface moves (drawer, toast stack, navigation menu morph).
  slow: '350ms',
});

// Easing curves. Built-in CSS keywords are too weak for UI motion; these are
// the house curves — never inline a cubic-bezier in component styles.
export const easing = stylex.defineConsts({
  // Enter/exit and state response: fast start, gentle settle.
  out: 'cubic-bezier(0.23, 1, 0.32, 1)',
  // On-screen movement between two resting positions (switch thumb,
  // navigation menu morph).
  inOut: 'cubic-bezier(0.77, 0, 0.175, 1)',
  // iOS-like drawer curve.
  drawer: 'cubic-bezier(0.32, 0.72, 0, 1)',
});

// Icon box sizes. Lucide icons default to 24px — size them with the `icon`
// styles in stylex-utils (`{...stylex.props(icon.md)}`), never the `size` prop.
export const iconSize = stylex.defineConsts({
  // Status dots and badges (avatar badge).
  xxs: '0.5rem',
  // Indicators inside 16px controls: checkbox, select item, chip remove.
  xs: '0.75rem',
  // Secondary chrome: breadcrumb separators, xs/sm buttons, tree rows.
  sm: '0.875rem',
  // Default for buttons, menus, inputs, triggers.
  md: '1rem',
  // Media and empty-state art.
  lg: '1.5rem',
});

export const stroke = stylex.defineConsts({
  border: '1px',
  focus: '2px',
  // Soft state ring (hover/active halo on slider thumbs etc.), like
  // Tailwind's ring-3.
  halo: '3px',
});

// Viewport breakpoints, mobile-first: style the narrowest layout as
// `default` and add keys upward. Several keys on one property are fine; the
// widest matching one wins. Keep the values in px: StyleX (0.19.1+) orders
// overlapping `defineConsts` media keys by width for px only, and rem keys
// can let a narrower breakpoint override a wider one.
export const breakpoint = stylex.defineConsts({
  sm: '@media (min-width: 640px)',
  md: '@media (min-width: 768px)',
  lg: '@media (min-width: 1024px)',
  xl: '@media (min-width: 1280px)',
  xxl: '@media (min-width: 1536px)',
});

// Container widths for popups, panels, and example layouts.
export const container = stylex.defineConsts({
  xs: '10rem',
  card: '16rem',
  sm: '18rem',
  md: '20rem',
  lg: '24rem',
  xl: '28rem',
  xxl: '32rem',
});

import * as stylex from '@stylexjs/stylex';

import { colors } from './tokens.stylex';

// Light and dark mode live in the tokens themselves: every color in
// `tokens.stylex.ts` is a `light-dark(light, dark)` pair, and the browser
// picks a side from the CSS `color-scheme` of the element. There is no dark
// theme to apply; set the scheme on <html> instead.
//
// `colorScheme` follows the OS by default. `data-theme="light"` or
// `data-theme="dark"` on the same element forces a mode (a manual toggle
// writes that attribute). Apply it to <html>, not a wrapper: dialogs and
// popovers portal to <body> and inherit the scheme from there. Scrollbars and
// native form controls follow it too.
//
//   <html {...stylex.props(colorScheme)}>
//
// Keep `color-scheme` in this CSS rule, never in an inline style: bundlers
// that lower `light-dark()` for older browsers (Next.js, LightningCSS) only
// see `color-scheme` set by stylesheet rules.
//
// `page` gives <body> the page colors from the tokens. It goes on <body>,
// not <html>: while <html> has no background, the body background fills the
// whole viewport, and a StyleX class on <body> wins over `body { background:
// … }` rules in @layer base, below every StyleX rule. Font smoothing is left
// to the app: it is a per-platform rendering choice, not a token.
//
//   <html {...stylex.props(colorScheme)}>
//     <body {...stylex.props(page)}>
const styles = stylex.create({
  colorScheme: {
    colorScheme: {
      default: 'light dark',
      '[data-theme="light"]': 'light',
      '[data-theme="dark"]': 'dark',
    },
  },
  page: {
    backgroundColor: colors.background,
    color: colors.foreground,
  },
});

export const colorScheme = styles.colorScheme;
export const page = styles.page;

// Brand or accent themes are `stylex.createTheme` calls over the same tokens.
// Values can be `light-dark()` pairs too, so a theme works in both modes:
//
//   export const brandTheme = stylex.createTheme(colors, {
//     primary: 'light-dark(oklch(0.55 0.2 260), oklch(0.7 0.16 260))',
//   });
//
// Themes are static by design: StyleX resolves `createTheme` at compile time,
// so add variations by writing more `createTheme` calls here, not by
// computing them at runtime. Apply one theme per element; two themes of the
// same token group on one element do not merge (the last one applied wins
// for the whole group). A theme on a nested element overrides the one above.
